1	// Modified from rakazo (Apache-2.0), github.com/elie222/rakazo@912c977
2	import type { GrokColorDef } from "@/lib/avatar";
3	import {
4	  ACTIVE_RUN_STATUSES,
5	  avatarIdentitySeed,
6	  DEFAULT_GROK_BOT_COLOR,
7	  GROK_BOT_COLORS,
8	  GROK_COLOR_LIST,
9	  organicAvatarPath,
10	  resolvePersonaColorDef,
11	  SHIPPED_BOT_AVATAR_CENTER,
12	  SHIPPED_BOT_AVATAR_SHAPE_KEYS,
13	  SHIPPED_BOT_AVATAR_SHAPES,
14	  SHIPPED_BOT_AVATAR_VIEWBOX,
15	  shippedBotAvatarShapePath,
16	  shippedHash,
17	} from "@/lib/avatar";
18	import { tokens } from "@/lib/tokens";
19	import type { CSSProperties } from "react";
20	import { memo, useId, useMemo, useSyncExternalStore } from "react";
21	import type { AvatarStyle } from "./avatar-style";
22	import { useAvatarStyle } from "./avatar-style";
23	import { cn } from "@/lib/utils";
24	
25	export type { GrokColorDef };
26	export { DEFAULT_GROK_BOT_COLOR, GROK_BOT_COLORS, GROK_COLOR_LIST, resolvePersonaColorDef };
27	
28	export const GROK_SHAPES = SHIPPED_BOT_AVATAR_SHAPES;
29	export const SHIPPED_SHAPE_KEYS = SHIPPED_BOT_AVATAR_SHAPE_KEYS;
30	const VIEWBOX = SHIPPED_BOT_AVATAR_VIEWBOX;
31	const CENTER = SHIPPED_BOT_AVATAR_CENTER;
32	
33	export const GROK_MASCOT_SHAPES = SHIPPED_SHAPE_KEYS.map(
34	  (k) => GROK_SHAPES[k] ?? FALLBACK_SHAPE_PATH,
35	);
36	
37	const FALLBACK_SHAPE_PATH = GROK_SHAPES.hex ?? "";
38	
39	export function resolvePersonaShape(identity: string, explicitShape?: string | null): string {
40	  if (explicitShape) {
41	    const explicit = GROK_SHAPES[explicitShape];
42	    if (explicit) return explicit;
43	  }
44	  let hash = shippedHash(identity);
45	  hash = Math.imul(hash ^ (hash >>> 16), 73244475);
46	  hash = Math.imul(hash ^ (hash >>> 13), 3266489909);
47	  const shapeIndex = ((hash ^ (hash >>> 16)) >>> 0) % SHIPPED_SHAPE_KEYS.length;
48	  const key = SHIPPED_SHAPE_KEYS[shapeIndex] ?? "hex";
49	  return GROK_SHAPES[key] ?? FALLBACK_SHAPE_PATH;
50	}
51	
52	export function parseBotAvatar(
53	  rawColor: string,
54	  _identity?: string,
55	): {
56	  color: string;
57	  shapeIndex?: number;
58	  isImage: boolean;
59	  imageUrl?: string;
60	} {
61	  if (!rawColor) return { color: "#F97316", isImage: false };
62	  // Only data: image URLs are rendered. Arbitrary http(s)/blob values in `color`
63	  // must not become <img src> (SSRF / tracking when other members view the bot).
64	  if (rawColor.startsWith("data:image/")) {
65	    return { color: "#F97316", isImage: true, imageUrl: rawColor };
66	  }
67	  if (rawColor.includes("::shape_")) {
68	    const parts = rawColor.split("::shape_");
69	    const rawShapeIdx = parts[1] ?? "0";
70	    const parsedShapeIdx = /^\d+$/.test(rawShapeIdx) ? Number(rawShapeIdx) : 0;
71	    const shapeIdx = Number.isSafeInteger(parsedShapeIdx) ? parsedShapeIdx : 0;
72	    return {
73	      color: parts[0] || "#F97316",
74	      shapeIndex: shapeIdx % SHIPPED_SHAPE_KEYS.length,
75	      isImage: false,
76	    };
77	  }
78	  return { color: rawColor, isImage: false };
79	}
80	
81	const AVATAR_HEX = /^#(?:[0-9a-fA-F]{3}|[0-9a-fA-F]{6})$/;
82	
83	export function defaultBotAvatarValue(rawColor: string): string {
84	  const parsed = parseBotAvatar(rawColor);
85	  if (rawColor && !parsed.isImage && AVATAR_HEX.test(parsed.color)) return parsed.color;
86	  return DEFAULT_GROK_BOT_COLOR;
87	}
88	
89	export interface BotAvatarProps {
90	  color: string;
91	  size?: number;
92	  status?: string;
93	  identity?: string;
94	  className?: string;
95	  variant?: AvatarStyle;
96	}
97	
98	export const BotAvatar = memo(function BotAvatar({
99	  color,
100	  size = 36,
101	  status,
102	  identity = "",
103	  className,
104	  variant,
105	}: BotAvatarProps) {
106	  const id = useId().replace(/[^a-zA-Z0-9-_]/g, "");
107	  const isWorking = ACTIVE_RUN_STATUSES.some((s) => s === status);
108	  const preferredVariant = useAvatarStyle();
109	
110	  const parsed = useMemo(() => parseBotAvatar(color, identity), [color, identity]);
111	  const effectiveId = identity || parsed.color || "agent";
112	
113	  const colorDef = useMemo(
114	    () => resolvePersonaColorDef(effectiveId, parsed.color),
115	    [effectiveId, parsed.color],
116	  );
117	
118	  const shapePath = useMemo(() => {
119	    if (parsed.shapeIndex !== undefined) {
120	      return shippedBotAvatarShapePath(parsed.shapeIndex);
121	    }
122	    return resolvePersonaShape(effectiveId);
123	  }, [parsed.shapeIndex, effectiveId]);
124	
125	  if (parsed.isImage && parsed.imageUrl) {
126	    return (
127	      <div
128	        className={cn(
129	          "rakazo-bot-avatar relative overflow-hidden rounded-full flex items-center justify-center select-none bg-secondary shrink-0 border border-border",
130	          className,
131	        )}
132	        data-working={isWorking}
133	        style={{
134	          width: size,
135	          height: size,
136	          boxShadow: isWorking
137	            ? "0 0 0 2px #3B82F6, 0 0 10px rgba(59,130,246,0.6)"
138	            : "0 2px 5px rgba(0,0,0,0.5)",
139	        }}
140	      >
141	        {isWorking ? (
142	          <svg
143	            className="rakazo-bot-avatar-ring absolute pointer-events-none"
144	            style={{
145	              inset: -4,
146	              width: size + 8,
147	              height: size + 8,
148	            }}
149	            viewBox="0 0 48 48"
150	            fill="none"
151	            aria-hidden="true"
152	          >
153	            <circle
154	              cx="24"
155	              cy="24"
156	              r="22"
157	              stroke="#3B82F6"
158	              strokeWidth="3.2"
159	              strokeLinecap="round"
160	              strokeDasharray="45 80"
161	            />
162	          </svg>
163	        ) : null}
164	        <img src={parsed.imageUrl} alt="" className="h-full w-full object-cover" />
165	      </div>
166	    );
167	  }
168	
169	  if (parsed.shapeIndex === undefined && (variant ?? preferredVariant) === "organic") {
170	    return (
171	      <OrganicAvatar
172	        color={colorDef.hex}
173	        identity={effectiveId}
174	        size={size}
175	        isWorking={isWorking}
176	        className={className}
177	      />
178	    );
179	  }
180	
181	  if (parsed.shapeIndex === undefined) {
182	    return (
183	      <RobotAvatar
184	        colorDef={colorDef}
185	        size={size}
186	        isWorking={isWorking}
187	        className={className}
188	        identity={effectiveId}
189	        gradientId={id}
190	      />
191	    );
192	  }
193	
194	  return (
195	    <div
196	      className={cn(
197	        "rakazo-bot-avatar grok-avatar-container relative inline-flex items-center justify-center shrink-0 select-none",
198	        className,
199	      )}
200	      style={{
201	        width: size,
202	        height: size,
203	      }}
204	      data-working={isWorking}
205	    >
206	      <svg
207	        className="rakazo-bot-avatar-ring absolute pointer-events-none"
208	        style={{
209	          inset: -4,
210	          width: size + 8,
211	          height: size + 8,
212	          filter: `drop-shadow(0 0 6px ${colorDef.light}) drop-shadow(0 0 10px #ffffff)`,
213	        }}
214	        viewBox="0 0 48 48"
215	        fill="none"
216	        aria-hidden="true"
217	      >
218	        <circle
219	          cx="24"
220	          cy="24"
221	          r="22"
222	          stroke={`url(#${id}-ring)`}
223	          strokeWidth="3.2"
224	          strokeLinecap="round"
225	          strokeDasharray="45 80"
226	        />
227	        <circle cx="43" cy="24" r="2.8" fill="#ffffff" />
228	        <defs>
229	          <linearGradient id={`${id}-ring`} x1="0%" y1="0%" x2="100%" y2="100%">
230	            <stop offset="0%" stopColor="#ffffff" stopOpacity="1" />
231	            <stop offset="60%" stopColor={colorDef.light} stopOpacity="0.9" />
232	            <stop offset="100%" stopColor={colorDef.light} stopOpacity="0" />
233	          </linearGradient>
234	        </defs>
235	      </svg>
236	      <svg
237	        viewBox={VIEWBOX}
238	        width={size}
239	        height={size}
240	        aria-hidden="true"
241	        className={cn(
242	          "overflow-visible transition-transform duration-300",
243	          isWorking
244	            ? "animate-pulse scale-[1.04] motion-reduce:animate-none"
245	            : "hover:scale-[1.03] motion-reduce:hover:scale-100",
246	        )}
247	        style={{
248	          filter: isWorking
249	            ? `drop-shadow(0 0 8px ${colorDef.light}) drop-shadow(0 0 2px #ffffff)`
250	            : "drop-shadow(0 2px 4px rgba(0,0,0,0.45))",
251	        }}
252	      >
253	        <defs>
254	          <linearGradient id={`grok-ink-${id}`} x1="0" y1="0" x2="1" y2="1">
255	            <stop offset="0%" stopColor={colorDef.light} />
256	            <stop offset="100%" stopColor={colorDef.dark} />
257	          </linearGradient>
258	        </defs>
259	        <g>
260	          <path d={shapePath} fill={`url(#grok-ink-${id})`} />
261	          <g fill={colorDef.eyeColor} className="grok-character-eyes">
262	            <ellipse cx={CENTER - 29} cy={CENTER - 8} rx={10} ry={7} />
263	            <ellipse cx={CENTER + 29} cy={CENTER - 8} rx={10} ry={7} />
264	          </g>
265	        </g>
266	      </svg>
267	    </div>
268	  );
269	});
270	
271	const VISOR_BORDER_PX = 1;
272	
273	function robotFaceLayout(size: number) {
274	  const visorW = Math.round(size * 0.68);
275	  const visorH = Math.round(size * 0.44);
276	  const visorInnerW = Math.max(0, visorW - VISOR_BORDER_PX * 2);
277	  const visorInnerH = Math.max(0, visorH - VISOR_BORDER_PX * 2);
278	  const preferredEyeW = Math.max(4, Math.round(size * 0.14));
279	  const preferredEyeH = Math.max(7, Math.round(size * 0.22));
280	  const preferredEyeGap = Math.max(3, Math.round(size * 0.1));
281	  const preferredSpan = preferredEyeW * 2 + preferredEyeGap;
282	  const scale = Math.min(1, visorInnerW / preferredSpan, visorInnerH / preferredEyeH);
283	  const eyeW = Math.floor(preferredEyeW * scale);
284	  const eyeH = Math.floor(preferredEyeH * scale);
285	  const eyeGap = Math.floor(preferredEyeGap * scale);
286	  const eyeRadius = Math.max(2, Math.round(eyeW * 0.5));
287	  return { visorW, visorH, eyeW, eyeH, eyeGap, eyeRadius };
288	}
289	
290	function RobotAvatar({
291	  colorDef,
292	  size,
293	  isWorking,
294	  className,
295	  identity,
296	  gradientId,
297	}: {
298	  colorDef: GrokColorDef;
299	  size: number;
300	  isWorking: boolean;
301	  className?: string;
302	  identity: string;
303	  gradientId: string;
304	}) {
305	  const seed = avatarIdentitySeed(identity || colorDef.hex);
306	  const eyeVariant = seed % 4;
307	  const idleDuration = (4.2 + ((seed * 7) % 28) / 10).toFixed(2);
308	  const idleDelay = (-(((seed * 13) % 45) / 10)).toFixed(2);
309	  const { visorW, visorH, eyeW, eyeH, eyeGap, eyeRadius } = robotFaceLayout(size);
310	  const eyeGlow = `0 0 4px #fff, 0 0 8px #fff, 0 0 14px ${colorDef.light}`;
311	  const idleEyeAnimation = {
312	    "--rakazo-eye-animation-name": `rakazo-eyes-idle-${eyeVariant}`,
313	    "--rakazo-eye-animation-duration": `${idleDuration}s`,
314	    "--rakazo-eye-animation-easing": "cubic-bezier(0.4, 0, 0.2, 1)",
315	    "--rakazo-eye-animation-delay": `${idleDelay}s`,
316	  } as CSSProperties;
317	  const workingEyeAnimation = {
318	    "--rakazo-eye-animation-name": "rakazo-eyes-working",
319	    "--rakazo-eye-animation-duration": "1.4s",
320	    "--rakazo-eye-animation-easing": "ease-in-out",
321	    "--rakazo-eye-animation-delay": "0s",
322	  } as CSSProperties;
323	
324	  return (
325	    <div
326	      className={cn(
327	        "rakazo-bot-avatar relative inline-flex shrink-0 items-center justify-center rounded-full select-none",
328	        className,
329	      )}
330	      data-working={isWorking}
331	      style={{
332	        width: size,
333	        height: size,
334	        background: `radial-gradient(circle at 35% 26%, ${colorDef.light}, ${colorDef.hex} 55%, ${colorDef.dark} 100%)`,
335	        boxShadow: isWorking
336	          ? `0 0 0 2px rgba(255,255,255,0.25), 0 0 ${Math.round(size * 0.45)}px ${colorDef.hex}`
337	          : `0 2px ${Math.max(4, Math.round(size * 0.15))}px rgba(0,0,0,0.4)`,
338	      }}
339	    >
340	      <svg
341	        className="rakazo-bot-avatar-ring pointer-events-none absolute"
342	        style={{
343	          inset: -4,
344	          width: size + 8,
345	          height: size + 8,
346	          filter: `drop-shadow(0 0 6px ${colorDef.light}) drop-shadow(0 0 10px #ffffff)`,
347	        }}
348	        viewBox="0 0 48 48"
349	        fill="none"
350	        aria-hidden="true"
351	      >
352	        <circle
353	          cx="24"
354	          cy="24"
355	          r="22"
356	          stroke={`url(#${gradientId}-ring)`}
357	          strokeWidth="3.2"
358	          strokeLinecap="round"
359	          strokeDasharray="45 80"
360	        />
361	        <circle cx="43" cy="24" r="2.8" fill="#ffffff" />
362	        <defs>
363	          <linearGradient id={`${gradientId}-ring`} x1="0%" y1="0%" x2="100%" y2="100%">
364	            <stop offset="0%" stopColor="#ffffff" stopOpacity="1" />
365	            <stop offset="60%" stopColor={colorDef.light} stopOpacity="0.9" />
366	            <stop offset="100%" stopColor={colorDef.light} stopOpacity="0" />
367	          </linearGradient>
368	        </defs>
369	      </svg>
370	      <div
371	        className="rakazo-bot-avatar-visor relative flex items-center justify-center overflow-hidden"
372	        style={{
373	          width: visorW,
374	          height: visorH,
375	          boxSizing: "border-box",
376	          borderRadius: Math.round(visorH * 0.52),
377	          background: "linear-gradient(180deg, #101014 0%, #030305 100%)",
378	          boxShadow: "inset 0 1.5px 3px rgba(0,0,0,0.95), 0 1px 1px rgba(255,255,255,0.18)",
379	          border: "1px solid rgba(255,255,255,0.14)",
380	        }}
381	      >
382	        {(["idle", "working"] as const).map((mode) => (
383	          <div
384	            key={mode}
385	            className={`rakazo-bot-avatar-eyes rakazo-bot-avatar-eyes-${mode} absolute inset-0 z-10 flex items-center justify-center`}
386	            style={{
387	              gap: eyeGap,
388	              ...(mode === "idle" ? idleEyeAnimation : workingEyeAnimation),
389	            }}
390	          >
391	            {[0, 1].map((eye) => (
392	              <span
393	                key={eye}
394	                className="block"
395	                style={{
396	                  width: eyeW,
397	                  height: eyeH,
398	                  borderRadius: eyeRadius,
399	                  backgroundColor: "#fff",
400	                  boxShadow: eyeGlow,
401	                }}
402	              />
403	            ))}
404	          </div>
405	        ))}
406	      </div>
407	    </div>
408	  );
409	}
410	
411	function OrganicAvatar({
412	  color,
413	  identity,
414	  size,
415	  isWorking,
416	  className,
417	}: {
418	  color: string;
419	  identity?: string;
420	  size: number;
421	  isWorking: boolean;
422	  className?: string;
423	}) {
424	  const reducedMotion = useSyncExternalStore(
425	    subscribeToReducedMotion,
426	    reducedMotionSnapshot,
427	    () => false,
428	  );
429	  const seed = avatarIdentitySeed(identity || color || DEFAULT_GROK_BOT_COLOR);
430	  const duration = `${4.8 + (seed % 24) / 10}s`;
431	  const shapeA = organicAvatarPath(seed);
432	  const shapeB = organicAvatarPath(seed, 0.42);
433	
434	  return (
435	    <svg
436	      viewBox="-60 -60 120 120"
437	      aria-hidden="true"
438	      className={cn("rakazo-organic-avatar overflow-visible select-none", className)}
439	      data-working={isWorking}
440	      data-shape-family={seed % 10}
441	      data-eye-pattern={seed % 4}
442	      style={{
443	        width: size,
444	        height: size,
445	        flex: "none",
446	      }}
447	    >
448	      {(["idle", "working"] as const).map((mode) => (
449	        <path
450	          key={mode}
451	          className={`rakazo-organic-avatar-body rakazo-organic-avatar-body-${mode}`}
452	          d={shapeA}
453	          fill={color}
454	          style={
455	            {
456	              "--rakazo-organic-path": `path("${shapeA}")`,
457	              filter:
458	                mode === "working"
459	                  ? `drop-shadow(0 0 ${Math.round(size * 0.16)}px ${color})`
460	                  : "drop-shadow(0 2px 3px rgba(0,0,0,.34))",
461	            } as CSSProperties
462	          }
463	        >
464	          {!reducedMotion ? (
465	            <animate
466	              attributeName="d"
467	              values={`${shapeA};${shapeB};${shapeA}`}
468	              dur={duration}
469	              repeatCount="indefinite"
470	            />
471	          ) : null}
472	        </path>
473	      ))}
474	      <g transform={`rotate(${(seed % 9) - 4})`}>
475	        {(["idle", "working"] as const).map((mode) => (
476	          <g
477	            key={mode}
478	            className={`rakazo-organic-avatar-eyes rakazo-organic-avatar-eyes-${mode}`}
479	            fill={tokens.background}
480	          >
481	            <rect x="-14" y="-12" width="7" height="24" rx="3.5" />
482	            <rect x="7" y="-12" width="7" height="24" rx="3.5" />
483	          </g>
484	        ))}
485	      </g>
486	    </svg>
487	  );
488	}
489	
490	const reducedMotionMedia = "(prefers-reduced-motion: reduce)";
491	
492	function reducedMotionSnapshot(): boolean {
493	  return window.matchMedia(reducedMotionMedia).matches;
494	}
495	
496	function subscribeToReducedMotion(onChange: () => void): () => void {
497	  const media = window.matchMedia(reducedMotionMedia);
498	  media.addEventListener("change", onChange);
499	  return () => media.removeEventListener("change", onChange);
500	}
501	
502	export function GrokShapePreview({
503	  shapeIndex,
504	  color,
505	  selected,
506	  onClick,
507	}: {
508	  shapeIndex: number;
509	  color: string;
510	  selected?: boolean;
511	  onClick?: () => void;
512	}) {
513	  const key = SHIPPED_SHAPE_KEYS[shapeIndex % SHIPPED_SHAPE_KEYS.length] ?? "hex";
514	  const path = shippedBotAvatarShapePath(shapeIndex);
515	  const colorDef = resolvePersonaColorDef("preview", color);
516	
517	  return (
518	    <button
519	      type="button"
520	      onClick={onClick}
521	      aria-label={key}
522	      aria-pressed={selected ?? false}
523	      className={cn(
524	        "relative flex size-11 items-center justify-center rounded-xl transition-transform hover:scale-105 active:scale-95 focus:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-popover",
525	        selected
526	          ? "ring-2 ring-primary ring-offset-2 ring-offset-popover bg-white/10"
527	          : "hover:bg-white/5",
528	      )}
529	    >
530	      <svg viewBox={VIEWBOX} className="size-8 overflow-visible" aria-hidden="true">
531	        <path d={path} fill={colorDef.light} />
532	        <g fill={colorDef.eyeColor}>
533	          <ellipse cx={CENTER - 29} cy={CENTER - 8} rx={10} ry={7} />
534	          <ellipse cx={CENTER + 29} cy={CENTER - 8} rx={10} ry={7} />
535	        </g>
536	      </svg>
537	    </button>
538	  );
539	}
