761	function isColorBright(hex: string): boolean {
762	  const c = expandHex(hex);
763	  const r = Number.parseInt(c.substring(0, 2), 16) || 0;
764	  const g = Number.parseInt(c.substring(2, 4), 16) || 0;
765	  const b = Number.parseInt(c.substring(4, 6), 16) || 0;
766	  const brightness = (r * 299 + g * 587 + b * 114) / 1000;
767	  return brightness > 180;
