770	function darkenHex(hex: string, percent: number): string {
771	  const num = Number.parseInt(expandHex(hex), 16);
772	  const factor = 1 - percent / 100;
773	  const r = Math.max(0, Math.floor(((num >> 16) & 255) * factor));
774	  const g = Math.max(0, Math.floor(((num >> 8) & 255) * factor));
775	  const b = Math.max(0, Math.floor((num & 255) * factor));
776	  return `#${((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1)}`;
777	}
